import{_ as e,c as t,o as a,a4 as o}from"./chunks/framework.P4k6vdAm.js";const f=JSON.parse('{"title":"PDF Task","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/pdf.md","filePath":"docs/tasks/pdf.md","lastUpdated":1793099931000}'),n={name:"docs/tasks/pdf.md"},s=o('<h1 id="pdf-task" tabindex="-1">PDF Task <a class="header-anchor" href="#pdf-task" aria-label="Permalink to &quot;PDF Task&quot;">​</a></h1><p>The PDF task generates a PDF document from an HTML template, or from formatted text. Optionally, you can combine it with an existing document by adding that document before or after the generated content.</p><h2 id="creating-a-pdf-document" tabindex="-1">Creating a PDF Document <a class="header-anchor" href="#creating-a-pdf-document" aria-label="Permalink to &quot;Creating a PDF Document&quot;">​</a></h2><p>Simple PDF generation can be accomplished by using the Rich Text editor to design the layout for the content, and the Context Data panel to insert data.</p><p>For advanced users or layouts, you can change the <code>Format</code> dropdown selection to <code>HTML (Raw)</code>. Using this method, you can accomplish much more complex designs for the PDF, and include features not available to the Text Editor mode. Examples of this include tables, images, colours, and other layout controls.</p><p>Additional options are available to format your PDF content. These are:</p><ul><li>Remove Margins</li><li>Landscape (default is portrait)</li><li>Scale factor - this adjusts the size of the content. 1 = 100% (normal size), 0.5 = 50% (half size), 2 = 200% (double size)</li></ul><h2 id="combining-documents" tabindex="-1">Combining Documents <a class="header-anchor" href="#combining-documents" aria-label="Permalink to &quot;Combining Documents&quot;">​</a></h2><p>You can also add content to an existing document. An example of this may be adding a static coversheet to the results of a survey submitted by AireForms. To do this, use the options on the <code>Advanced Settings</code> tab under <code>Attachment Settings</code> to insert the base64 version of the existing PDF, and choose whether you want to Append or Prepend it to your new content (PDF Content).</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>The generated PDF can be used from the Context Data panel in subsequent tasks, for example as an <a href="/docs/tasks/email.html">Email</a> attachment.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>You can chain multiple PDF tasks, combining the output of one with the next.</li></ul>',13),i=[s];function d(r,c,l,h,u,m){return a(),t("div",null,i)}const b=e(n,[["render",d]]);export{f as __pageData,b as default};
